const dbGet = async q => (await fetch(`${URL_}/rest/v1/orders?${q}`,{headers:hdr})).json();
const dbPatch = async (id,body) => fetch(`${URL_}/rest/v1/orders?id=eq.${id}`,{method:'PATCH',headers:{...hdr,Prefer:'return=representation'},body:JSON.stringify(body)});

const log = (...a)=>console.log(...a);

