const callList = async () => (await (await fetch(`${BASE}/api/consumer/orders`,{headers:{Cookie:cookie}})).json()).orders||[];
const callAck = async id => { const r = await fetch(`${BASE}/api/consumer/orders/${id}/acknowledge`,{method:'POST',headers:{Cookie:cookie}}); return {status:r.status, body:await r.json().catch(()=>({}))}; };

// client-side rule mirror (from OrderCard.tsx)
const isResolved = o => ((o.status==='declined'||o.status==='cancelled') && !!o.acknowledged_at) || o.delivery_status==='delivered' || !!o.collected_at || !!o.received_at;
const where = o => isResolved(o) ? 'HISTORY' : 'ACTIVE';

log('\n--- STEP 1: before acknowledge (should be ACTIVE) ---');
let list = await callList();
let d = list.find(o=>o.id===declined.id), c = list.find(o=>o.id===cancelled.id);
log('declined  ack=',d.acknowledged_at,'->', where(d));
log('cancelled ack=',c.acknowledged_at,'->', where(c));

