list = await callList();
d = list.find(o=>o.id===declined.id); c = list.find(o=>o.id===cancelled.id);
log('declined  ack=',d.acknowledged_at,'->', where(d));
log('cancelled ack=',c.acknowledged_at,'->', where(c));

log('\n--- PROBE A: acknowledge again = idempotent ---');
log(await callAck(declined.id));

log('\n--- PROBE B: acknowledge a NON-declined/cancelled order (expect 409) ---');
