if(active){ log('target status=',active.status,'->', await callAck(active.id)); } else log('no pending/approved order to probe');

log('\n--- PROBE C: acknowledge with NO session cookie (expect 401) ---');
{ const r = await fetch(`${BASE}/api/consumer/orders/${declined.id}/acknowledge`,{method:'POST'}); log({status:r.status, body:await r.json().catch(()=>({}))}); }

