const cart = { L1: item };
const browser = await chromium.launch({executablePath:'/usr/bin/chromium-browser',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});
const ctx = await browser.newContext({viewport:{width:412,height:1000}});
await ctx.addInitScript(c=>localStorage.setItem('yff_cart_v1', c), JSON.stringify(cart));
