const errs=[]; page.on('console',m=>{if(m.type()==='error')errs.push(m.text().slice(0,140));});
page.on('pageerror',e=>errs.push('PAGEERR: '+e.message.slice(0,140)));
await page.goto('http://localhost:3000/consumer/cart',{waitUntil:'networkidle',timeout:45000});
await page.waitForTimeout(2500);
const heading = await page.locator('h2').first().innerText().catch(()=>'(none)');
const hasBack = await page.getByRole('button',{name:'Back'}).count();
const bodyHas = t => page.evaluate(s=>document.body.innerText.includes(s), t);
console.log('URL:', page.url());
console.log('heading:', heading);
console.log('back arrow present:', hasBack);
console.log('shows "Papaya":', await bodyHas('Papaya'));
